= EventScript_RockSmash
lockall
goto_if_unset FLAG_BADGE03_GET EventScript_CantSmashRock
checkpartymove MOVE_ROCK_SMASH
goto_if_eq VAR_RESULT PARTY_SIZE EventScript_CantSmashRock
setfieldeffectargument 0 VAR_RESULT
bufferpartymonnick STR_VAR_1 VAR_RESULT
buffermovename STR_VAR_2 MOVE_ROCK_SMASH
msgboxyesno	This rock appears to be breakable. Would you like to use ROCK SMASH?
goto_if_eq VAR_RESULT NO EventScript_CancelSmash
msgbox	STR_VAR_1 used STR_VAR_2!
closemessage
dofieldeffect FLDEFF_USE_ROCK_SMASH
waitstate
goto EventScript_SmashRock
end
@ Use rock smash from party menu
goto EventScript_UseRockSmash
= EventScript_UseRockSmash
lockall
dofieldeffect FLDEFF_USE_ROCK_SMASH
waitstate
goto EventScript_SmashRock
end
= EventScript_SmashRock
applymovement VAR_LAST_TALKED Movement_SmashRock
waitmovement 0
removeobject VAR_LAST_TALKED
specialvar VAR_RESULT TryUpdateRusturfTunnelState
goto_if_eq VAR_RESULT TRUE EventScript_EndSmash
special RockSmashWildEncounter
goto_if_eq VAR_RESULT FALSE EventScript_EndSmash
waitstate
releaseall
end
= EventScript_EndSmash
releaseall
end
= EventScript_CancelSmash
closemessage
releaseall
end
= EventScript_CantSmashRock
msgbox	It's a rugged rock, but a POKéMON may be able to smash it.
releaseall
end
= EventScript_StrengthBoulder
lockall
goto_if_unset FLAG_BADGE04_GET EventScript_CantStrength
goto_if_set FLAG_SYS_USE_STRENGTH EventScript_CheckActivatedBoulder
checkpartymove MOVE_STRENGTH
goto_if_eq VAR_RESULT PARTY_SIZE EventScript_CantStrength
setfieldeffectargument 0 VAR_RESULT
msgboxyesno	It's a big boulder, but a POKéMON may be able to push it aside.Would you like to use STRENGTH?
goto_if_eq VAR_RESULT NO EventScript_CancelStrength
closemessage
dofieldeffect FLDEFF_USE_STRENGTH
waitstate
goto EventScript_ActivateStrength
end
= EventScript_ActivateStrength
setflag FLAG_SYS_USE_STRENGTH
msgbox	STR_VAR_1 used STRENGTH!STR_VAR_1's STRENGTH made it possible to move boulders around!
releaseall
end
= EventScript_CancelStrength
closemessage
releaseall
end
= EventScript_CantStrength
msgbox	It's a big boulder, but a POKéMON may be able to push it aside.
releaseall
end
= EventScript_CheckActivatedBoulder
msgbox	STRENGTH made it possible to move boulders around.
releaseall
end
